    "Category": "వర్గం",
    "Category totals will appear when the backend has recorded DNS events.": "బ్యాకెండ్ DNS సంఘటనలు నమోదు చేసినప్పుడు వర్గాల మొత్తాలు కనిపిస్తాయి.",
    "Check the saved history before retrying if the connection failed while the request was in progress.": "అభ్యర్థన జరుగుతున్నప్పుడు కనెక్షన్ విఫలమైతే, మళ్లీ ప్రయత్నించే ముందు సేవ్ చేసిన చరిత్రను చూడండి.",
