    "AUDIT REPORT · #": "తనిఖీ నివేదిక · #",
    "on the server. It must be configured outside this dashboard. Configuration does not mean policy enforcement is implemented.": "సర్వర్‌లో. దీన్ని ఈ డ్యాష్‌బోర్డ్ వెలుపల కాన్ఫిగర్ చేయాలి. కాన్ఫిగర్ చేశారని విధాన అమలు అందుబాటులో ఉందని అర్థం కాదు.",
    "Unable to load the latest audit.": "తాజా తనిఖీని లోడ్ చేయలేకపోయాం.",
    "For safety, discovery is limited to private IPv4 subnets no larger than /16.": "భద్రత కోసం, /16 కంటే పెద్దవి కాని ప్రైవేట్ IPv4 సబ్‌నెట్‌లకే గుర్తింపు పరిమితం.",
    "Select an inventory device before starting a device audit.": "పరికర తనిఖీ ప్రారంభించే ముందు జాబితాలోని పరికరాన్ని ఎంచుకోండి.",
    "Select a saved audit report before generating a plan.": "ప్రణాళిక రూపొందించే ముందు సేవ్ చేసిన తనిఖీ నివేదికను ఎంచుకోండి.",
    "Confirm that policy planning will save proposed policies.": "విధాన ప్రణాళిక ప్రతిపాదనలను సేవ్ చేస్తుందని నిర్ధారించండి.",
    "Select at least one saved policy for dry-run evaluation.": "డ్రై-రన్ అంచనా కోసం కనీసం ఒక సేవ్ చేసిన విధానాన్ని ఎంచుకోండి.",
    "Confirm that dry-run evaluation will save a plan record.": "డ్రై-రన్ అంచనా ప్రణాళిక రికార్డును సేవ్ చేస్తుందని నిర్ధారించండి.",
    "The backend returned an invalid JSON response.": "బ్యాకెండ్ చెల్లని JSON స్పందన ఇచ్చింది.",
    "devices returned.": "పరికరాలు వచ్చాయి.",
    "devices currently returned by inventory.": "ప్రస్తుతం జాబితాలో ఉన్న పరికరాలు.",
    "SUMMARY": "సారాంశం",
    "TOP 20": "మొదటి 20",
    "state": "స్థితి",
    "SAVED": "సేవ్ చేయబడింది",
    "SAVED AUDIT REQUIRED": "సేవ్ చేసిన తనిఖీ అవసరం",
    "SAVES POLICIES": "విధానాలను సేవ్ చేస్తుంది",
    "RECORDED DATA PROJECTION": "నమోదైన డేటా అంచనా",
    "SAVES PLAN RECORD": "ప్రణాళిక రికార్డును సేవ్ చేస్తుంది",
    "Policy #": "విధానం #",
    "Name": "పేరు",
    "Target": "లక్ష్యం",
    "Saved plan #": "సేవ్ చేసిన ప్రణాళిక #",
    "PROJECTION ONLY": "అంచనా మాత్రమే",
    "POLICIES INCLUDED": "చేర్చిన విధానాలు",
    "AFFECTED QUERIES": "ప్రభావిత ప్రశ్నలు",
    "PROJECTED BLOCKED QUERIES": "నిలిపివేయబడవచ్చని అంచనా వేసిన ప్రశ్నలు",
    "Persisted plan record check": "సేవ్ చేసిన ప్రణాళిక రికార్డు తనిఖీ",
    "Reading saved plan…": "సేవ్ చేసిన ప్రణాళికను చదువుతోంది…",
    "was returned by the plan endpoint.": "ప్రణాళిక API నుంచి వచ్చింది.",
    "Stored plan values:": "సేవ్ చేసిన ప్రణాళిక విలువలు:",
    "Stored projected blocked queries:": "అంచనా వేసి సేవ్ చేసిన నిలిపివేత ప్రశ్నలు:",
    "TOTAL": "మొత్తం",
    ". The backend does not persist or expose this audit-to-policy linkage.": "। ఈ తనిఖీ-విధాన అనుసంధానాన్ని బ్యాకెండ్ సేవ్ చేయదు లేదా అందించదు.",
    "match the backend’s current generation rule.": "బ్యాకెండ్ ప్రస్తుత రూపొందింపు నియమానికి సరిపోవాలి.",
    "Policy planning response received for audit #": "ఈ తనిఖీకి విధాన ప్రణాళిక స్పందన వచ్చింది:",
    "saved policy ID": "సేవ్ చేసిన విధాన ID",
