    "Audit completion confirmed by the backend": "ஆய்வு முடிந்ததை பின்புலம் உறுதிப்படுத்தியது",
    "Audit was not confirmed": "ஆய்வு முடிந்தது உறுதிப்படுத்தப்படவில்லை",
    "BACKEND RESPONSE": "பின்புல பதில்",
    "BACKEND-SAVED RECORDS": "பின்புலத்தில் சேமித்த பதிவுகள்",
    "Backend connection": "பின்புல இணைப்பு",
    "Backend execution details": "பின்புல செயலாக்க விவரங்கள்",
