    "Capabilities & limitations": "திறன்கள் & வரம்புகள்",
    "Capability status": "திறன் நிலை",
    "Category": "வகை",
    "Category totals will appear when the backend has recorded DNS events.": "பின்புலம் DNS நிகழ்வுகளைப் பதிவு செய்ததும் வகை மொத்தங்கள் தோன்றும்.",
    "Check the saved history before retrying if the connection failed while the request was in progress.": "கோரிக்கை நடக்கும்போது இணைப்பு துண்டானால், மீண்டும் முயல்வதற்கு முன் சேமித்த வரலாற்றைப் பாருங்கள்.",
    "Checking backend status…": "பின்புல நிலையைச் சரிபார்க்கிறது…",
