    "Could not refresh inventory after the scan.": "ஸ்கேன் முடிந்ததும் சாதனப் பட்டியலைப் புதுப்பிக்க முடியவில்லை.",
    "DEVICE DETAILS": "சாதன விவரங்கள்",
