    "Enforcement capability": "செயல்படுத்தும் திறன்",
    "Evaluates all devices currently in inventory and their recorded DNS events.": "பட்டியலிலுள்ள எல்லாச் சாதனங்களையும் அவற்றின் பதிவு செய்யப்பட்ட DNS நிகழ்வுகளையும் மதிப்பிடுகிறது.",
    "Evaluates one selected inventory device and its recorded DNS events.": "தேர்ந்தெடுத்த சாதனத்தையும் அதன் பதிவு செய்யப்பட்ட DNS நிகழ்வுகளையும் மதிப்பிடுகிறது.",
    "Events": "நிகழ்வுகள்",
    "FINDINGS IN SUMMARY": "சுருக்கத்தில் கண்டறிதல்கள்",
    "FINDINGS RETURNED": "பெறப்பட்ட கண்டறிதல்கள்",
