    "Report details are unavailable": "அறிக்கை விவரங்கள் கிடைக்கவில்லை",
    "Reports could not be loaded": "அறிக்கைகளை ஏற்ற முடியவில்லை",
    "Reversible": "மீளச் செய்யக்கூடியது",
    "Review evidence-based reports about inventory metadata and recorded DNS activity.": "சாதனப் பட்டியல் மெட்டாடேட்டா மற்றும் பதிவு செய்த DNS செயல்பாடு குறித்த ஆதார அறிக்கைகளைப் பாருங்கள்.",
    "Risk": "ஆபத்து",
    "Run an audit or select a saved report to view its results.": "முடிவுகளைக் காண ஆய்வை இயக்கவும் அல்லது சேமித்த அறிக்கையைத் தேர்ந்தெடுக்கவும்.",
    "Saved audit history is unavailable.": "சேமித்த ஆய்வு வரலாறு கிடைக்கவில்லை.",
    "Saved policies are unavailable.": "சேமித்த கொள்கைகள் கிடைக்கவில்லை.",
    "Select a saved report to view its results.": "முடிவுகளைக் காண சேமித்த அறிக்கையைத் தேர்ந்தெடுக்கவும்.",
    "Select a snapshot to inspect its saved state and checksum result.": "சேமித்த நிலை மற்றும் செக்சம் முடிவைப் பார்க்க ஸ்னாப்ஷாட்டைத் தேர்ந்தெடுக்கவும்.",
    "Select saved policies for this projection": "இந்த மதிப்பீட்டிற்கு சேமித்த கொள்கைகளைத் தேர்ந்தெடுக்கவும்",
    "Select saved policy": "சேமித்த கொள்கையைத் தேர்ந்தெடுக்கவும்",
    "Selected saved report": "தேர்ந்தெடுத்த சேமித்த அறிக்கை",
    "Service": "சேவை",
    "Showing 5 of": "இதில் 5 காட்டப்படுகிறது:",
    "Showing events requested for": "கோரிய நிகழ்வுகள் காட்டப்படுகின்றன:",
    "Snapshot #": "ஸ்னாப்ஷாட் #",
    "Source": "மூலம்",
    "Status and available details below are read from the policy APIs. This page provides no approval, apply, or enforcement controls.": "கீழுள்ள நிலையும் விவரங்களும் கொள்கை API-களிலிருந்து படிக்கப்படுகின்றன. இந்தப் பக்கத்தில் ஒப்புதல் அல்லது செயல்படுத்தும் கட்டுப்பாடுகள் இல்லை.",
    "The API reports verification for this policy; this status alone does not confirm traffic-level protection.": "இந்தக் கொள்கைக்கான சரிபார்ப்பை API தெரிவிக்கிறது; இந்த நிலை மட்டும் போக்குவரத்துப் பாதுகாப்பை உறுதிப்படுத்தாது.",
    "The backend name is read from": "பின்புலப் பெயர் இங்கிருந்து படிக்கப்படுகிறது:",
    "The backend reports no execution record for this policy. No execution result is available.": "இந்தக் கொள்கைக்கான செயலாக்கப் பதிவு இல்லை என பின்புலம் தெரிவிக்கிறது. செயலாக்க முடிவும் கிடைக்கவில்லை.",
    "The backend returned no configuration snapshot records.": "பின்புலம் அமைப்பு ஸ்னாப்ஷாட் பதிவுகளை வழங்கவில்லை.",
    "The dry-run response was successful, but persisted-plan details could not be fully reloaded.": "சோதனை ஓட்டப் பதில் வெற்றியடைந்தது; ஆனால் சேமித்த திட்ட விவரங்களை முழுமையாக மீண்டும் ஏற்ற முடியவில்லை.",
    "The saved history entry exists, but the backend did not return its report summary.": "சேமித்த வரலாற்றுப் பதிவு உள்ளது; ஆனால் அறிக்கைச் சுருக்கத்தை பின்புலம் வழங்கவில்லை.",
    "The summary was returned, but individual evidence could not be loaded.": "சுருக்கம் கிடைத்தது; தனிப்பட்ட ஆதாரங்களை ஏற்ற முடியவில்லை.",
    "There are no grouped DNS events to display.": "காட்டுவதற்கு குழுவாக்கிய DNS நிகழ்வுகள் இல்லை.",
    "This completed audit returned an empty findings list.": "முடிந்த இந்த ஆய்வு காலியான கண்டறிதல் பட்டியலை வழங்கியது.",
    "This is a status flag only. The snapshot rollback endpoint is not implemented and no rollback action is available here.": "இது நிலைக் குறியீடு மட்டுமே. ஸ்னாப்ஷாட் மீட்டமைப்பு API செயல்படுத்தப்படவில்லை; இங்கே மீட்டமைப்பு நடவடிக்கையும் இல்லை.",
    "This page only reads backend status. It does not expose settings changes or indicate that network traffic is protected.": "இந்தப் பக்கம் பின்புல நிலையை மட்டும் படிக்கிறது. அமைப்புகளை மாற்றவோ வலையமைப்புப் போக்குவரத்து பாதுகாக்கப்படுகிறது எனக் காட்டவோ செய்யாது.",
    "USER-INITIATED ACTION": "பயனர் தொடங்கிய செயல்",
    "Version": "பதிப்பு",
    "SOURCE": "மூலம்",
    "NETWORK GUARDIAN": "வலையமைப்புக் காவலர்",
