    "SEE YOUR NETWORK CLEARLY. PROTECT IT SAFELY.": "உங்கள் வலையமைப்பைத் தெளிவாகப் பாருங்கள். பாதுகாப்பாகக் காக்குங்கள்.",
    "Advertising": "விளம்பரம்",
