    "Informational": "தகவல்",
    "SELECTED POLICY · #": "தேர்ந்தெடுத்த கொள்கை · #",
    "READ-ONLY POLICY STATUS": "படிக்க மட்டும் கொள்கை நிலை",
    "AUDIT REPORT · #": "ஆய்வு அறிக்கை · #",
    "This does not indicate whether the state is currently applied.": "அந்த நிலை தற்போது செயல்படுத்தப்பட்டுள்ளதா என்பதை இது குறிக்காது.",
    "The API reports findings, not a compromise verdict or risk score. An empty result means no findings were returned by this audit run; it is not a guarantee of safety. Historical audit metadata does not include the target device ID or failed-run records.": "API கண்டறிதல்களை மட்டுமே தெரிவிக்கிறது; சாதனம் சமரசம் செய்யப்பட்டதாகத் தீர்ப்பளிக்கவோ ஆபத்து மதிப்பெண் வழங்கவோ இல்லை. காலி முடிவு இந்த ஆய்வில் கண்டறிதல்கள் வரவில்லை என்பதே; பாதுகாப்புக்கான உறுதி அல்ல. முந்தைய ஆய்வு மெட்டாடேட்டாவில் இலக்கு சாதன ID அல்லது தோல்வியுற்ற பதிவுகள் இல்லை.",
    "Read-only service health, backend configuration, and API capability information.": "சேவை நிலை, பின்புல அமைப்பு, API திறன்கள் குறித்த படிக்க மட்டும் தகவல்.",
    "on the server. It must be configured outside this dashboard. Configuration does not mean policy enforcement is implemented.": "சேவையகத்தில். இதை இந்தப் பலகைக்கு வெளியே அமைக்க வேண்டும். அமைப்பு இருப்பது கொள்கை செயல்படுத்தல் உள்ளது என்று பொருளல்ல.",
    "Unable to load the latest audit.": "சமீபத்திய ஆய்வை ஏற்ற முடியவில்லை.",
    "For safety, discovery is limited to private IPv4 subnets no larger than /16.": "பாதுகாப்புக்காக, /16-ஐ விடப் பெரியதல்லாத தனியார் IPv4 சப்நெட்களுக்கு மட்டுமே கண்டறிதல் வரையறுக்கப்பட்டுள்ளது.",
    "Select an inventory device before starting a device audit.": "சாதன ஆய்வைத் தொடங்குவதற்கு முன் பட்டியலிலிருந்து சாதனத்தைத் தேர்ந்தெடுக்கவும்.",
    "Select a saved audit report before generating a plan.": "திட்டத்தை உருவாக்குமுன் சேமித்த ஆய்வு அறிக்கையைத் தேர்ந்தெடுக்கவும்.",
    "Confirm that policy planning will save proposed policies.": "கொள்கைத் திட்டமிடல் பரிந்துரைகளைச் சேமிக்கும் என்பதை உறுதிப்படுத்தவும்.",
    "Select at least one saved policy for dry-run evaluation.": "சோதனை மதிப்பீட்டிற்கு குறைந்தது ஒரு சேமித்த கொள்கையைத் தேர்ந்தெடுக்கவும்.",
    "Confirm that dry-run evaluation will save a plan record.": "சோதனை மதிப்பீடு திட்டப் பதிவைச் சேமிக்கும் என்பதை உறுதிப்படுத்தவும்.",
    "The backend returned an invalid JSON response.": "பின்புலம் தவறான JSON பதிலை வழங்கியது.",
    "devices returned.": "சாதனங்கள் கிடைத்தன.",
    "devices currently returned by inventory.": "சாதனங்கள் தற்போது பட்டியலில் உள்ளன.",
