    "Persisted plan record check": "சேமித்த திட்டப் பதிவைச் சரிபார்த்தல்",
    "Reading saved plan…": "சேமித்த திட்டத்தைப் படிக்கிறது…",
    "was returned by the plan endpoint.": "திட்ட API வழங்கியது.",
