    "Generate saved proposals from completed audits and evaluate selected policies against recorded data.": "ಪೂರ್ಣಗೊಂಡ ಪರಿಶೀಲನೆಗಳಿಂದ ಪ್ರಸ್ತಾವನೆಗಳನ್ನು ರಚಿಸಿ, ದಾಖಲಾಗಿರುವ ಮಾಹಿತಿಯ ವಿರುದ್ಧ ಆಯ್ದ ನೀತಿಗಳನ್ನು ಮೌಲ್ಯಮಾಪನ ಮಾಡಿ.",
    "HOSTNAME": "ಹೋಸ್ಟ್ ಹೆಸರು",
