    "No categorized DNS events": "ವರ್ಗೀಕರಿಸಿದ DNS ಘಟನೆಗಳಿಲ್ಲ",
    "No evidence details were included in this finding.": "ಈ ಅಂಶದಲ್ಲಿ ಸಾಕ್ಷ್ಯದ ವಿವರಗಳು ಸೇರಿಲ್ಲ.",
    "No report selected": "ವರದಿ ಆಯ್ಕೆಯಾಗಿಲ್ಲ",
    "No saved audit reports": "ಉಳಿಸಿದ ಪರಿಶೀಲನಾ ವರದಿಗಳಿಲ್ಲ",
    "No verification explanation was returned.": "ಪರಿಶೀಲನೆಯ ವಿವರಣೆ ಹಿಂತಿರುಗಿಲ್ಲ.",
    "Not exposed by the policy detail endpoint": "ನೀತಿ ವಿವರ API ಈ ಮಾಹಿತಿಯನ್ನು ಒದಗಿಸುವುದಿಲ್ಲ",
    "Recovery status": "ಮರುಪಡೆಯುವಿಕೆ ಸ್ಥಿತಿ",
    "Report details are unavailable": "ವರದಿ ವಿವರಗಳು ಲಭ್ಯವಿಲ್ಲ",
    "Reports could not be loaded": "ವರದಿಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ",
    "Reversible": "ಹಿಂದಿರುಗಿಸಬಹುದು",
    "Review evidence-based reports about inventory metadata and recorded DNS activity.": "ಸಾಧನ ಪಟ್ಟಿ ಮೆಟಾಡೇಟಾ ಮತ್ತು ದಾಖಲಾಗಿರುವ DNS ಚಟುವಟಿಕೆಯ ಸಾಕ್ಷ್ಯಾಧಾರಿತ ವರದಿಗಳನ್ನು ಪರಿಶೀಲಿಸಿ.",
    "Risk": "ಅಪಾಯ",
    "Run an audit or select a saved report to view its results.": "ಫಲಿತಾಂಶಗಳನ್ನು ನೋಡಲು ಪರಿಶೀಲನೆ ನಡೆಸಿ ಅಥವಾ ಉಳಿಸಿದ ವರದಿ ಆಯ್ಕೆಮಾಡಿ.",
    "Saved audit history is unavailable.": "ಉಳಿಸಿದ ಪರಿಶೀಲನಾ ಇತಿಹಾಸ ಲಭ್ಯವಿಲ್ಲ.",
    "Saved policies are unavailable.": "ಉಳಿಸಿದ ನೀತಿಗಳು ಲಭ್ಯವಿಲ್ಲ.",
    "Select a saved report to view its results.": "ಫಲಿತಾಂಶ ನೋಡಲು ಉಳಿಸಿದ ವರದಿ ಆಯ್ಕೆಮಾಡಿ.",
    "Select a snapshot to inspect its saved state and checksum result.": "ಉಳಿಸಿದ ಸ್ಥಿತಿ ಮತ್ತು ಚೆಕ್ಸಮ್ ಫಲಿತಾಂಶ ನೋಡಲು ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ ಆಯ್ಕೆಮಾಡಿ.",
    "Select saved policies for this projection": "ಈ ಅಂದಾಜಿಗೆ ಉಳಿಸಿದ ನೀತಿಗಳನ್ನು ಆಯ್ಕೆಮಾಡಿ",
    "Select saved policy": "ಉಳಿಸಿದ ನೀತಿ ಆಯ್ಕೆಮಾಡಿ",
    "Selected saved report": "ಆಯ್ದ ಉಳಿಸಿದ ವರದಿ",
    "Service": "ಸೇವೆ",
    "Showing 5 of": "ಒಟ್ಟು ಇದರಲ್ಲಿ 5 ತೋರಿಸಲಾಗುತ್ತಿದೆ:",
    "Showing events requested for": "ಕೋರಿದ ಘಟನೆಗಳನ್ನು ತೋರಿಸಲಾಗುತ್ತಿದೆ:",
    "Snapshot #": "ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ #",
    "Source": "ಮೂಲ",
    "Status and available details below are read from the policy APIs. This page provides no approval, apply, or enforcement controls.": "ಕೆಳಗಿನ ಸ್ಥಿತಿ ಮತ್ತು ವಿವರಗಳನ್ನು ನೀತಿ APIಗಳಿಂದ ಓದಲಾಗಿದೆ. ಈ ಪುಟದಲ್ಲಿ ಅನುಮೋದನೆ ಅಥವಾ ಜಾರಿ ನಿಯಂತ್ರಣಗಳಿಲ್ಲ.",
    "The API reports verification for this policy; this status alone does not confirm traffic-level protection.": "ಈ ನೀತಿಯ ಪರಿಶೀಲನಾ ಸ್ಥಿತಿಯನ್ನು API ವರದಿ ಮಾಡುತ್ತದೆ; ಈ ಸ್ಥಿತಿ ಮಾತ್ರ ಟ್ರಾಫಿಕ್ ರಕ್ಷಣೆಯನ್ನು ದೃಢಪಡಿಸುವುದಿಲ್ಲ.",
    "The backend name is read from": "ಬ್ಯಾಕೆಂಡ್ ಹೆಸರನ್ನು ಇಲ್ಲಿಂದ ಓದಲಾಗುತ್ತದೆ:",
    "The backend reports no execution record for this policy. No execution result is available.": "ಈ ನೀತಿಗೆ ಕಾರ್ಯಗತಗೊಳಿಸುವ ದಾಖಲೆ ಇಲ್ಲವೆಂದು ಬ್ಯಾಕೆಂಡ್ ತಿಳಿಸಿದೆ. ಫಲಿತಾಂಶ ಲಭ್ಯವಿಲ್ಲ.",
    "The backend returned no configuration snapshot records.": "ಬ್ಯಾಕೆಂಡ್ ಕಾನ್ಫಿಗರೇಶನ್ ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ ದಾಖಲೆಗಳನ್ನು ನೀಡಿಲ್ಲ.",
    "The dry-run response was successful, but persisted-plan details could not be fully reloaded.": "ಡ್ರೈ-ರನ್ ಯಶಸ್ವಿಯಾಯಿತು; ಆದರೆ ಉಳಿಸಿದ ಯೋಜನೆಯ ವಿವರಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ಮತ್ತೆ ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ.",
    "The saved history entry exists, but the backend did not return its report summary.": "ಇತಿಹಾಸದ ದಾಖಲೆಯಿದೆ, ಆದರೆ ಬ್ಯಾಕೆಂಡ್ ವರದಿ ಸಾರಾಂಶ ನೀಡಿಲ್ಲ.",
    "The summary was returned, but individual evidence could not be loaded.": "ಸಾರಾಂಶ ಬಂದಿದೆ; ಆದರೆ ಪ್ರತ್ಯೇಕ ಸಾಕ್ಷ್ಯಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ.",
    "There are no grouped DNS events to display.": "ತೋರಿಸಲು ಗುಂಪು ಮಾಡಿದ DNS ಘಟನೆಗಳಿಲ್ಲ.",
    "This completed audit returned an empty findings list.": "ಪೂರ್ಣಗೊಂಡ ಈ ಪರಿಶೀಲನೆ ಖಾಲಿ ಅಂಶಗಳ ಪಟ್ಟಿಯನ್ನು ನೀಡಿದೆ.",
    "This is a status flag only. The snapshot rollback endpoint is not implemented and no rollback action is available here.": "ಇದು ಸ್ಥಿತಿ ಸೂಚನೆ ಮಾತ್ರ. ಸ್ನ್ಯಾಪ್‌ಶಾಟ್ ಹಿಂತಿರುಗಿಸುವ API ಜಾರಿಗೊಂಡಿಲ್ಲ; ಇಲ್ಲಿ ಅಂತಹ ಕ್ರಮ ಲಭ್ಯವಿಲ್ಲ.",
    "This page only reads backend status. It does not expose settings changes or indicate that network traffic is protected.": "ಈ ಪುಟ ಬ್ಯಾಕೆಂಡ್ ಸ್ಥಿತಿಯನ್ನು ಮಾತ್ರ ಓದುತ್ತದೆ. ಸೆಟ್ಟಿಂಗ್ ಬದಲಾವಣೆ ಅಥವಾ ನೆಟ್‌ವರ್ಕ್ ಟ್ರಾಫಿಕ್ ರಕ್ಷಣೆಯ ಭರವಸೆ ನೀಡುವುದಿಲ್ಲ.",
    "USER-INITIATED ACTION": "ಬಳಕೆದಾರ ಆರಂಭಿಸಿದ ಕ್ರಮ",
    "Version": "ಆವೃತ್ತಿ",
    "SOURCE": "ಮೂಲ",
    "NETWORK GUARDIAN": "ನೆಟ್‌ವರ್ಕ್ ರಕ್ಷಕ",
    "Network": "ನೆಟ್‌ವರ್ಕ್",
    "scope": "ವ್ಯಾಪ್ತಿ",
    "identity unavailable": "ಗುರುತು ಲಭ್ಯವಿಲ್ಲ",
    "Unknown hostname": "ತಿಳಿಯದ ಹೋಸ್ಟ್ ಹೆಸರು",
    "No device linked": "ಯಾವುದೇ ಸಾಧನಕ್ಕೆ ಜೋಡಿಸಿಲ್ಲ",
    "not provided": "ನೀಡಿಲ್ಲ",
    "SEE YOUR NETWORK CLEARLY. PROTECT IT SAFELY.": "ನಿಮ್ಮ ನೆಟ್‌ವರ್ಕ್ ಅನ್ನು ಸ್ಪಷ್ಟವಾಗಿ ನೋಡಿ. ಸುರಕ್ಷಿತವಾಗಿ ರಕ್ಷಿಸಿ.",
    "Advertising": "ಜಾಹೀರಾತು",
    "Tracking/Analytics": "ಟ್ರ್ಯಾಕಿಂಗ್/ವಿಶ್ಲೇಷಣೆ",
    "Telemetry": "ಟೆಲಿಮೆಟ್ರಿ",
