    "Medium": "ಮಧ್ಯಮ",
    "Low": "ಕಡಿಮೆ",
    "Informational": "ಮಾಹಿತಿಪರ",
    "SELECTED POLICY · #": "ಆಯ್ದ ನೀತಿ · #",
    "READ-ONLY POLICY STATUS": "ಓದಲು ಮಾತ್ರ ನೀತಿ ಸ್ಥಿತಿ",
    "AUDIT REPORT · #": "ಪರಿಶೀಲನಾ ವರದಿ · #",
    "This does not indicate whether the state is currently applied.": "ಸ್ಥಿತಿ ಈಗ ಜಾರಿಯಲ್ಲಿದೆಯೇ ಎಂಬುದನ್ನು ಇದು ಸೂಚಿಸುವುದಿಲ್ಲ.",
    "The API reports findings, not a compromise verdict or risk score. An empty result means no findings were returned by this audit run; it is not a guarantee of safety. Historical audit metadata does not include the target device ID or failed-run records.": "API ಕಂಡುಬಂದ ಅಂಶಗಳನ್ನು ಮಾತ್ರ ವರದಿ ಮಾಡುತ್ತದೆ; ಸಾಧನ ಹ್ಯಾಕ್ ಆಗಿದೆ ಎಂಬ ತೀರ್ಪು ಅಥವಾ ಅಪಾಯ ಅಂಕವಲ್ಲ. ಖಾಲಿ ಫಲಿತಾಂಶದಲ್ಲಿ ಈ ಪರಿಶೀಲನೆಗೆ ಅಂಶಗಳು ಬಂದಿಲ್ಲ ಅಷ್ಟೇ; ಇದು ಸುರಕ್ಷತೆಯ ಖಾತರಿ ಅಲ್ಲ. ಹಳೆಯ ಪರಿಶೀಲನಾ ಮೆಟಾಡೇಟಾದಲ್ಲಿ ಗುರಿ ಸಾಧನ ID ಅಥವಾ ವಿಫಲ ಪ್ರಯತ್ನಗಳ ದಾಖಲೆ ಇರುವುದಿಲ್ಲ.",
    "Read-only service health, backend configuration, and API capability information.": "ಸೇವೆಯ ಆರೋಗ್ಯ, ಬ್ಯಾಕೆಂಡ್ ಕಾನ್ಫಿಗರೇಶನ್ ಮತ್ತು API ಸಾಮರ್ಥ್ಯಗಳ ಓದಲು ಮಾತ್ರ ಮಾಹಿತಿ.",
    "on the server. It must be configured outside this dashboard. Configuration does not mean policy enforcement is implemented.": "ಸರ್ವರ್‌ನಲ್ಲಿ. ಇದನ್ನು ಈ ಡ್ಯಾಶ್‌ಬೋರ್ಡ್ ಹೊರಗೆ ಕಾನ್ಫಿಗರ್ ಮಾಡಬೇಕು. ಕಾನ್ಫಿಗರೇಶನ್ ಎಂದರೆ ನೀತಿ ಜಾರಿ ಇದೆ ಎಂದಲ್ಲ.",
    "Unable to load the latest audit.": "ಇತ್ತೀಚಿನ ಪರಿಶೀಲನೆಯನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ.",
    "For safety, discovery is limited to private IPv4 subnets no larger than /16.": "ಸುರಕ್ಷತೆಗಾಗಿ, /16 ಮೀರದ ಖಾಸಗಿ IPv4 ಸಬ್‌ನೆಟ್‌ಗಳಿಗೆ ಪತ್ತೆ ಸೀಮಿತವಾಗಿದೆ.",
    "Select an inventory device before starting a device audit.": "ಸಾಧನ ಪರಿಶೀಲನೆ ಆರಂಭಿಸುವ ಮೊದಲು ಪಟ್ಟಿಯಿಂದ ಸಾಧನ ಆಯ್ಕೆಮಾಡಿ.",
    "Select a saved audit report before generating a plan.": "ಯೋಜನೆ ರಚಿಸುವ ಮೊದಲು ಉಳಿಸಿದ ಪರಿಶೀಲನಾ ವರದಿ ಆಯ್ಕೆಮಾಡಿ.",
    "Confirm that policy planning will save proposed policies.": "ನೀತಿ ಯೋಜನೆಯು ಪ್ರಸ್ತಾವಿತ ನೀತಿಗಳನ್ನು ಉಳಿಸುತ್ತದೆ ಎಂದು ದೃಢೀಕರಿಸಿ.",
    "Select at least one saved policy for dry-run evaluation.": "ಡ್ರೈ-ರನ್ ಮೌಲ್ಯಮಾಪನಕ್ಕೆ ಕನಿಷ್ಠ ಒಂದು ಉಳಿಸಿದ ನೀತಿ ಆಯ್ಕೆಮಾಡಿ.",
    "Confirm that dry-run evaluation will save a plan record.": "ಡ್ರೈ-ರನ್ ಮೌಲ್ಯಮಾಪನ ಯೋಜನಾ ದಾಖಲೆಯನ್ನು ಉಳಿಸುತ್ತದೆ ಎಂದು ದೃಢೀಕರಿಸಿ.",
    "The backend returned an invalid JSON response.": "ಬ್ಯಾಕೆಂಡ್ ಅಮಾನ್ಯ JSON ಪ್ರತಿಕ್ರಿಯೆ ನೀಡಿದೆ.",
    "devices returned.": "ಸಾಧನಗಳು ಲಭ್ಯವಾದವು.",
    "devices currently returned by inventory.": "ಸಾಧನಗಳು ಪ್ರಸ್ತುತ ಪಟ್ಟಿಯಲ್ಲಿ ಬಂದಿವೆ.",
    "SUMMARY": "ಸಾರಾಂಶ",
